{
  "segments": [
    {
      "name": "1. Founder-instructor preparing the next cohort of a paid course",
      "buyer": "Independent founder-instructor who controls the course website and purchasing decisions.",
      "market": "Paid cohort-based courses with previous students and a publicly announced upcoming cohort.",
      "problem": "Needs fresh alumni testimonials for the next enrollment page; collection competes with launch preparation.",
      "access": "Check public Maven listings, then instructor websites for launch dates, previous cohorts, and published business emails.",
      "tradeoff": "Clear deadline and direct authority; willingness to pay remains unverified, and launches may be infrequent."
    },
    {
      "name": "2. Owner of a small web-design agency completing client projects",
      "buyer": "Owner of a two-to-ten-person web-design agency who manages project handoffs and marketing purchases.",
      "market": "Agencies publishing recent client launches and maintaining their own portfolio websites.",
      "problem": "Needs client testimonials after project completion, before clients become difficult to reengage.",
      "access": "Find agencies through public agency directories; verify recent launches and owner contact details on their websites.",
      "tradeoff": "Repeated project handoffs could support recurring payment, but client approvals complicate activation and ownership."
    },
    {
      "name": "3. Bootstrapped software founder preparing a launch-page refresh",
      "buyer": "Founder who owns website changes and software purchases for an early paid software product.",
      "market": "Small software businesses with existing customers and a publicly discussed launch or website refresh",
      "problem": "Needs usable customer proof before publishing a new landing page or launch announcement.",
      "access": "Review public founder launch posts and product websites; verify existing customers and an explicit launch trigger.",
      "tradeoff": "Direct purchasing authority and self-service familiarity, but limited customer evidence and free-tool preferences may constrain payment."
    }
  ],
  "firstBuyerWhy": "Start with course founder-instructors: an upcoming enrollment deadline, reachable alumni, and purchasing authority can converge in one person. This is a hypothesis, not established demand. Agency owners win instead if a ",
  "buyingMotion": "Sales-assisted",
  "paymentPath": "Verify current pricing, paid-plan boundaries, and checkout before outreach. Offer a brief workflow walkthrough, then buyer-operated setup using existing functionality. Confirm the buyer's required capability, acceptable ",
  "firstExperiment": {
    "problem": "Determine whether an upcoming course launch makes alumni testimonial collection urgent enough to purchase.",
    "identifyProspects": "Use public Maven listings as a candidate source, subject to an access check. Qualify on the instructor's own website: previous students, an upcoming cohort date, founder control, and a published business contact. Exclude first-cohort courses and contacts requiring guessed or private addresses.",
    "channel": "Individual, relevant emails to publicly listed business addresses.",
    "channelRationale": "Direct email tests deadline, authority, and payment questions without assuming traffic or an audience. It requires manual research but no initial media spend. Compared with community templates, conversations can surface objections sooner; compared with partner recruitment, access requires fewer gate"
  ,
    "firstAction": "Check whether public course listings and instructor websites yield qualified buyers with published business emails. Also verify current product pricing and checkout. If access fails, revise the prospect source before sending; do not treat inaccessible prospects as rejected demand.",
    "activityTarget": {
      "quantity": 8,
      "activity": "Research, qualify, and send individual invitations to up to eight founder-instructors; record exclusions and access barriers."
    },
    "resources": {
      "assumedMinutes":  30,
      "tools": [
        "Browser",
        "Spreadsheet for qualification and learning notes"
      ],
      "directSpend": 0,
      "assumptions": "Assume a browser, existing email account, and founder time. Allow three hours for access checks, research, and invitations, plus one hour reserved for consented conversations. No paid database, audience, automation, or "
    },
    "commercialLearning": "Ask about the launch deadline, current testimonial workaround, consequences of delay, purchase authority, and acceptable price. Test activation through creating a collection form, requesting permissioned alumni proof, and publishing one usable testimonial where feasible. Establish whether a ",
    "continueWhen": "A buyer describes a consequential launch deadline, owns the decision, completes a meaningful activation step, and agrees to a concrete paid next step at a verified price. Continue buyer-led onboarding; count a customer only after payment confirmation.",
    "adjustWhen": "A buyer has urgent need but identifies a specific blocker such as alumni permission, setup effort, or unclear paid value. Change that part of the test. For silence, inspect access, delivery, and relevance before drawing demand conclusions.",
    "stopWhen": "Stop this segment-channel combination if qualified conversations consistently show no consequential deadline, an adequate existing workaround, or no reason to pay for available capabilities. If public contact access fails, stop outreach through that source rather than inferring absent demand."
  },
  "alternatives": [
    {
      "channel": "Self-service testimonial-request template in a relevant course-creator community",
      "comparison": "Lower marginal delivery effort but requires useful content and moderator permission. Can use free tools, although product access must be verified. Commercial evidence is slower without existing traffic; community access,",
      "preferWhen": "Qualified buyers explicitly prefer independent setup, and an accessible community permits relevant resource sharing.",
      "firstAction": "Inspect a public course-creator community's rules and request permission to share a practical alumni-testimonial request template."
    },
    {
      "channel": "Referral distribution through independent course-website designers",
      "comparison": "Higher relationship-building effort and slower payment evidence because a partner sits between seller and buyer. Initial conversations require no spend; any referral economics remain unverified. Public designer port",
      "preferWhen": "Buyer conversations show website designers control testimonial publishing, and a designer expresses concrete interest in introducing a suitable client.",
      "firstAction": "Find a designer publicly specializing in course websites and ask how clients currently collect and publish testimonials."
    }
  ],
  "messages": [
    {
      "subject": "Alumni testimonials for your next cohort?",
      "body": "Are you gathering alumni testimonials for an upcoming course launch? I’m testing whether Senja fits that workflow. Would a brief walkthrough using your current process be useful? If it fits, we can discuss a paid plan before you commit."
    },
    {
      "subject": "May I send a collection-workflow outline?",
      "body": "May I send a short outline for requesting alumni testimonials and publishing them on a course page? If this is a current priority, we could compare it with your existing process. If not, I won’t follow up again."
    }
  ],
  "positioning": "For founder-instructors preparing their next cohort, Senja offers a way to collect alumni testimonials and prepare proof for course pages and launch content. Test workflow fit and paid value; do not promise conversion or",
  "unknowns": [
    "No market research or external verification establishes demand, buyer accessibility, or willingness to pay.",
    "Public directory access, contact availability, and relevant outreach requirements need checking before sending.",
    "Current pricing, free-tier boundaries, checkout availability, and necessary paid capabilities remain unverified."
  ],
  "recommendationBasis": {
    "segments": [
      "s1",
      "s3"
    ],
    "acquisitionChannels": [
      "s1",
      "s2"
    ],
    "outreachTemplates": [
      "s1",
      "s4"
    ],
    "firstTenPlaybook": [
      "s1",
      "s3"
    ],
    "thirtyDayPlan": [
      "s1",
      "s3"
    ]
  }
}

